7	import {validateMessage} from './validation.js';
8	import type {ValidationResult} from './validation.js';
9	import {PerSessionLock} from '../../shared/perSessionLock.js';
10	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
11	import type {SessionStore} from '../../types/sessionStore.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
46	    }
47	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
48	    return wsErrorHandler(ws, async () => answerFrame(ws, session, sessionStore, validation));
49	  };
50	}
51	
52	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
53	async function answerInTurn(
54	  ws: WebSocket,
55	  session: ChatSession,
56	  orchestrator: ChatOrchestrator,
57	  validation: ValidationResult,
58	  signal: AbortSignal | undefined
59	): Promise<void> {
60	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
61	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
62	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
63	    return;
64	  }
65	  const startedAt = Date.now();
66	  try {
67	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
68	  } finally {
69	    endTurn(ws, session, signal, startedAt);
70	  }
71	}
72	
73	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
74	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
75	  if (signal?.aborted) {
76	    log.info('message', 'turn abandoned: its socket closed', {
77	      sessionId: session.sessionId,
78	      elapsedMs: Date.now() - startedAt,
79	    });
80	    return;
81	  }
82	  sendStreamEnd(ws);
83	}
84	
85	async function answerUserMessage(
86	  ws: WebSocket,
87	  session: ChatSession,
88	  orchestrator: ChatOrchestrator,
89	  validation: ValidationResult,
90	  signal: AbortSignal | undefined
91	): Promise<void> {
92	  const message = validation.valid ? validation.data : undefined;
93	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
94	  // unreachable: only user_message frames call this path
95	}
96	
97	async function answerFrame(
98	  ws: WebSocket,
99	  session: ChatSession,
100	  sessionStore: SessionStore | undefined,
101	  validation: ValidationResult
102	): Promise<void> {
103	  if (!validation.valid) {
104	    log.warn('message', 'validation failed', {error: validation.error});
105	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
106	    return;
107	  }
108	
109	  const message = validation.data;
110	  if (message.type === 'ping') handlePing(ws, message.timestamp);
111	  if (message.type === 'list_sessions') return handleListSessions(ws, session, sessionStore, message);
112	}
113	
114	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
115	function isUserMessageFrame(rawMessage: unknown): boolean {
116	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
117	}
118	
119	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
120	  try {
121	    await action();
122	  } catch (error) {
123	    const message = error instanceof Error ? error.message : 'Unknown error';
124	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
125	    log.error('message', 'handling error', {error: message, code});
126	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
127	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
128	      return;
129	    }
130	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
131	  }
132	}
133	
134	async function handleUserMessage(
135	  ws: WebSocket,
136	  session: ChatSession,
137	  orchestrator: ChatOrchestrator,
138	  content: string,
139	  signal: AbortSignal | undefined
140	): Promise<void> {
141	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
142	
143	  const userEntry = createUserEntry(content);
144	  const userIndex = appendEntry(session, userEntry);
145	  sendUpsert(ws, userIndex, userEntry);
146	
147	  const parser = new ThinkingTagParser();
148	  const state: StreamState = {
149	    thinkingIndex: null,
150	    assistantIndex: null,
151	    suppressOutput: false,
152	    sentAssistantIndices: [],
153	  };
154	
155	  let textChunkCount = 0;
156	
157	  try {
158	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
159	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
160	      if (signal?.aborted) break;
161	      textChunkCount = logChunk(chunk, textChunkCount);
162	      processChunk(ws, session, state, parser, chunk);
163	    }
164	  } finally {
165	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
166	    flushHeldText(ws, session, state, parser);
167	    closeCutOff(ws, session, state, 'thinkingIndex');
168	    closeCutOff(ws, session, state, 'assistantIndex');
169	  }
170	
171	  if (textChunkCount > 0) {
172	    log.debug('stream', `received ${textChunkCount} text chunks`);
173	  }
174	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
175	}
176	
177	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
178	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
179	  if (chunk.type === 'text') return textChunkCount + 1;
180	
181	  if (textChunkCount > 0) {
182	    log.debug('stream', `received ${textChunkCount} text chunks`);
183	  }
184	
185	  if (chunk.type === 'tool_result') {
186	    log.debug('stream', 'tool_result chunk', {
187	      messageCount: chunk.clientMessages.length,
188	      types: chunk.clientMessages.map(m => m.type),
189	    });
190	    return 0;
191	  }
192	
193	  log.debug('stream', 'chunk', {type: chunk.type});
194	  return 0;
195	}
196	
197	function processChunk(
198	  ws: WebSocket,
199	  session: ChatSession,
200	  state: StreamState,
201	  parser: ThinkingTagParser,
202	  chunk: MessageChunk
203	): void {
204	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
205	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
206	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
207	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
208	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
209	}
210	
211	function processTextChunk(
212	  ws: WebSocket,
213	  session: ChatSession,
214	  state: StreamState,
215	  parser: ThinkingTagParser,
216	  text: string
217	): void {
218	  const segments = parser.push(text);
219	  for (const segment of segments) {
220	    handleTextSegment(ws, session, state, segment);
221	  }
222	}
